/* Session 5 uses the same chapter, note, search and progress model as prior units. */
function s5Figure(id){
 const f=regionsSession5.figures.find(f=>f.id===id);if(!f)return '';
 return `<figure id="s5fig-${wmEscape(id)}" class="s5-figure s5-figure-${f.kind}" data-s5-figure="${wmEscape(id)}"><div class="s5-figure-heading"><strong>${wmEscape(f.title)}</strong><a href="${f.src}" target="_blank" rel="noopener" aria-label="打开大图：${wmEscape(f.title)}">打开大图 ↗</a></div><a class="s5-image-link" href="${f.src}" target="_blank" rel="noopener"><img src="${f.src}" width="${f.width}" height="${f.height}" alt="${wmEscape(f.title+'。'+f.caption)}" loading="lazy" decoding="async"></a><figcaption>${wmEscape(f.caption)}</figcaption></figure>`;
}
function s5UnitBody(u){
 const sources=regionsSession5.sources.filter(s=>s.routes.includes(`${u.chapter}/${u.id}`));
 return `<p class="wm-orientation">${wmEscape(u.intro)}</p>`+u.sections.map((s,i)=>`<section class="article-section wm-content-section"><h2 id="book-${u.chapter}-${u.id}-${i+1}">${wmEscape(s.title)}</h2>${s.paragraphs.map(p=>`<p>${wmEscape(p)}</p>`).join('')}${s.table?wmTable(s.table):''}${s.figures?.length?`<div class="s5-figures${s.figures.every(id=>regionsSession5.figures.find(f=>f.id===id).kind==='labels')?' s5-figures-labels':''}">${s.figures.map(s5Figure).join('')}</div>`:''}${s.conclusion?`<p class="s5-conclusion"><strong>学到这里，应该能说：</strong>${wmEscape(s.conclusion)}</p>`:''}</section>`).join('')+`${u.links.length?`<nav class="wm-related" aria-label="相关知识"><strong>相关主题</strong><div>${u.links.map(l=>`<a href="#read/${l.route}">${wmEscape(l.label)} →</a>`).join('')}</div></nav>`:''}${sources.length?`<p class="s5-references">核对依据：${sources.map(s=>`<a href="${s.url}" target="_blank" rel="noopener">${wmEscape(s.title)} ↗</a>`).join('；')}</p>`:''}`;
}
for(const ch of regionsSession5.chapters)bookChapters.push({...ch,framework:false});
for(const u of regionsSession5.units)bookUnits.push({...u,framework:false,origins:[],body:s5UnitBody(u)});
knowledgeTopics.push(...regionsSession5.topics);
knowledgeCases.push(...regionsSession5.cases);
Object.assign(knowledgeFuture.find(f=>f.id==='regions'),{added:true,status:'勃艮第与博若莱已收录',summary:'第11章法规与第15、16章：环境、品种、园址和工艺连到风格、品质及成本。其他产区后续继续整理。',href:'#chapter/15'});
const s5PreviousReview=bookReviewView;
bookReviewView=function(id){
 const ch=regionsSession5.chapters.find(c=>c.id===Number(id));if(!ch)return s5PreviousReview(id);
 const units=regionsSession5.units.filter(u=>u.chapter===ch.id),pages=regionsSession5.pages.filter(p=>p.routes.some(r=>r.startsWith(ch.id+'/')));
 const links=routes=>routes.map(r=>{const u=bookUnits.find(u=>`${u.chapter}/${u.id}`===r);return u?`<a href="#read/${r}">${wmEscape(u.title)} →</a>`:''}).join('<br>');
 const figs=regionsSession5.figures.filter(f=>units.some(u=>u.sections.some(s=>s.figures?.includes(f.id))));
 return `<main id="main" class="wrap book-review wm-review"><a class="back" href="#chapter/${ch.id}">← 第 ${ch.id} 章</a><header class="page-intro"><div class="eyebrow">CHAPTER ${ch.id} · SOURCE RECORD</div><h1 class="page-title">资料与配图核对记录</h1><p>${wmEscape(ch.title)} · 课本p.${ch.pages} · ${units.length}个阅读单元</p></header><section><h2>本批资料状态</h2><p>41张照片逐页登记：课本p.103–106、119–129，共15页；讲义p.65–90，共26页（含上一课收束及地图专页）。知识按课本主题整合，图片裁出主体并在图下独立解释；重复图合并，原件留在本地。</p><p>两份Word为课堂转写，文件中未含可播放的嵌入音频；本次依据转写文字，未核听原音频。${wmEscape(regionsSession5.intake.gap)}</p><p><strong>练习册p.7–9及机构参考答案仍待提供。</strong>本章知识地图中的解释与应用为自编自查，不冒充原练习册或官方评分。</p></section><section><h2>每页知识与图示的去向</h2><div class="comparison-wrap"><table class="comparison wm-review-table"><thead><tr><th>来源页</th><th>知识与图</th><th>正文去向</th></tr></thead><tbody>${pages.map(p=>`<tr><th scope="row">${p.type==='textbook'?'课本':'讲义'}p.${p.page}<small> · 照片${p.sourceId}</small></th><td>${wmEscape(p.topic)}<p class="fine">${wmEscape(p.visual)}</p></td><td>${links(p.routes)}</td></tr>`).join('')}</tbody></table></div></section><section><h2>本章配图 · ${figs.length}幅</h2><ul class="wm-figure-list">${figs.map(f=>{const u=units.find(u=>u.sections.some(s=>s.figures?.includes(f.id)));return `<li><a href="#read/${u.chapter}/${u.id}/s5fig-${f.id}">${wmEscape(f.title)} →</a><span>图下有独立说明，可打开原尺寸裁图</span></li>`}).join('')}</ul></section><details class="review-fold"><summary>表述差异与版本范围</summary><ul><li>PDO／PGI来源要求以欧盟委员会核对；讲义的“DOPG”未当作标准名称沿用。非欧盟制度不得一概说成完全不限制。</li><li>Petit Chablis按独立法定产区解释；Grand Cru标示按课本处理。Climat、具名地块与一级／特级等级不混同。</li><li>面积、产量占比与等级数量保留为教材／讲义统计口径，不声称是2026年最新统计。</li><li>霜冻风险不以“芽里没有水”解释；泥灰岩与石灰岩的当地分布不扩成普遍品种限制或直接口味因果。</li><li>整串、二氧化碳与半二氧化碳工艺分开；保留压榨和后续酵母完成发酵，以及是否带皮的分叉。</li><li>教材“适量无害”的旧健康表述按WHO更新；不把本章当作各地即时法律或医学剂量建议。</li><li>转写中不清的专名、创始人和价格延伸不猜写为确定事实；人物照片保留原图身份。</li></ul></details><details class="review-fold"><summary>转写文件与核对来源</summary><ul>${regionsSession5.intake.transcripts.map(t=>`<li>${wmEscape(t)}</li>`).join('')}</ul>${regionsSession5.sources.map(s=>`<p><a href="${s.url}" target="_blank" rel="noopener">${wmEscape(s.title)} ↗</a></p>`).join('')}</details></main>`;
};
const s5PreviousPractice=learnerPracticeSection;
learnerPracticeSection=function(){return s5PreviousPractice()+`<section class="learner-practice"><div class="eyebrow">APPLY IT TO A REGION</div><h2>法规、勃艮第与博若莱 · 自编自查</h2><p>${regionsSession5.topics.length}个主题，练习解释、比较与应用。先写结论与原因，再看提示；本课练习册第7–9页原题尚待提供。</p><div class="learner-chapters">${regionsSession5.chapters.map(c=>`<article><h3>第${c.id}章 · ${wmEscape(c.title)}</h3>${learnerChapterPractice(c.id)}</article>`).join('')}</div></section>`;};
